BEGIN;

INSERT INTO pulsar.t_cln_concept
(
    concept_code, concept_name, concept_type, definition,
    concept_aliases, source_section, source_page, source_excerpt,
    is_active, updated_at
)
VALUES
('COLONY_METHODOLOGY', 'Colony Methodology', 'METHODOLOGY', 'A hybrid agile software development methodology combining the Scrum framework and the Unified Process. It organizes work through linked events, inquiries, reactions, condition tables, and five lifecycle phases, with automated planning as a central mechanism.', ARRAY['Colony', 'Colony method']::text[], 'Section 6: Colony methodology', 8, 'hybrid of Scrum and UP', TRUE, CURRENT_TIMESTAMP),
('AGILE_APPROACH', 'Agile approach', 'METHODOLOGY', 'An approach in which decisions are made in short iterations, results are delivered frequently, teams participate in critical decisions, and interaction with clients is emphasized.', ARRAY['Agile', 'Agile software development', 'ASD']::text[], 'Section 4.1: Agile approach', 4, 'short iterations', TRUE, CURRENT_TIMESTAMP),
('AGILE_MANIFESTO', 'Agile Manifesto', 'PRINCIPLE_FRAMEWORK', 'The manifesto presented in the article through four value preferences: people and interactions, working software, customer participation, and responding to change are valued over their paired alternatives.', ARRAY['Agile statement']::text[], 'Section 4.1: Agile approach', 4, 'People and interactions', TRUE, CURRENT_TIMESTAMP),
('SCRUM_FRAMEWORK', 'Scrum framework', 'METHODOLOGY', 'A framework consisting of Scrum teams and their associated roles, events, products, and rules. The article describes the Sprint as its central time-boxed unit.', ARRAY['Scrum']::text[], 'Section 4.2: The Scrum framework', 4, 'roles, events, products, and rules', TRUE, CURRENT_TIMESTAMP),
('UNIFIED_PROCESS', 'Unified Process', 'METHODOLOGY', 'An iterative, object-oriented software development process addressing architecture, deployment, and maintenance. Work is organized into iterations that include analysis, design, implementation, and testing.', ARRAY['UP']::text[], 'Section 4.3: Unified Process', 6, 'iterative, object-oriented', TRUE, CURRENT_TIMESTAMP),
('REQUIREMENTS_ENGINEERING', 'Requirements Engineering', 'DISCIPLINE', 'The requirements-related discipline underlying the Colony approach, including elicitation, discovery, interviews, collaboration, analysis, prioritization, modeling, validation, and verification.', ARRAY['RE', 'Requirements Engineering (RE)']::text[], 'Sections 3, 5.8, 6', 4, 'Requirements Engineering', TRUE, CURRENT_TIMESTAMP),
('PRODUCT', 'Product', 'SCRUM_ARTIFACT', 'A deliverable intended to provide value, with a clear boundary, known stakeholders, and defined users or customers; it may be a service, physical product, or abstract product.', ARRAY[]::text[], 'Section 4.2: Scrum framework', 5, 'deliver value', TRUE, CURRENT_TIMESTAMP),
('PRODUCT_BACKLOG', 'Product Backlog', 'SCRUM_ARTIFACT', 'A prioritized list of work or requirements for a product. In Colony, it is initially formed by identifying Primary Use Cases and subsequently evolves through Use Case inquiries during the system lifetime.', ARRAY['PB']::text[], 'Sections 4.2, 6.1, 8', 5, 'list of everything', TRUE, CURRENT_TIMESTAMP),
('SPRINT_BACKLOG', 'Sprint Backlog', 'SCRUM_ARTIFACT', 'The Scrum work plan for a Sprint. In Colony, it is also the plan for completing an Element through Elaboration, Construction, Transition, Maintenance, and related inquiries.', ARRAY['SB']::text[], 'Sections 4.2, 6.2, 8', 5, 'subset of the PB', TRUE, CURRENT_TIMESTAMP),
('PRODUCT_BACKLOG_ITEM', 'Product Backlog Item', 'SCRUM_ARTIFACT', 'A generic term for an item in the Product Backlog; the article gives user stories, bugs, and tasks as examples.', ARRAY['PBI']::text[], 'Section 4.2: Scrum framework', 5, 'generic term for any item', TRUE, CURRENT_TIMESTAMP),
('SPRINT_BACKLOG_ITEM', 'Sprint Backlog Item', 'COLONY_TERM', 'A term used by the Colony methodology for Product Backlog items selected for a Sprint; the article explicitly notes that SBI is not an official Scrum term.', ARRAY['SBI']::text[], 'Section 6: Colony methodology', 8, 'not an official term', TRUE, CURRENT_TIMESTAMP),
('INCREMENT', 'Increment', 'SCRUM_ARTIFACT', 'The accumulated value of Product Backlog items completed in a Sprint together with the value of increments from previous Sprints. In Colony, an increment is delivered through a usable, validated colony of Use Cases.', ARRAY[]::text[], 'Sections 4.2 and 8', 5, 'sum of all the PB items', TRUE, CURRENT_TIMESTAMP),
('SPRINT', 'Sprint', 'SCRUM_EVENT', 'A time-boxed period of one month or less during which a potentially releasable product increment is created.', ARRAY[]::text[], 'Section 4.2: Scrum framework', 5, 'time-boxed period', TRUE, CURRENT_TIMESTAMP),
('SPRINT_PLANNING', 'Sprint Planning', 'SCRUM_EVENT', 'The event at the beginning of a Sprint in which the Scrum team decides which Product Backlog items to work on and how the work will be done.', ARRAY[]::text[], 'Section 4.2: Scrum framework', 5, 'beginning of a sprint', TRUE, CURRENT_TIMESTAMP),
('DAILY_SCRUM', 'Daily Scrum', 'SCRUM_EVENT', 'A daily 15-minute event in which the development team inspects progress and plans work for the next 24 hours.', ARRAY[]::text[], 'Sections 4.2 and 8', 5, '15-minute event', TRUE, CURRENT_TIMESTAMP),
('SPRINT_REVIEW', 'Sprint Review', 'SCRUM_EVENT', 'An event at the end of a Sprint in which the team and stakeholders inspect the increment and provide feedback for future improvement.', ARRAY[]::text[], 'Sections 4.2 and 8', 5, 'at the end of a sprint', TRUE, CURRENT_TIMESTAMP),
('SPRINT_RETROSPECTIVE', 'Sprint Retrospective', 'SCRUM_EVENT', 'An event after the Sprint Review in which the Scrum team reflects on performance and identifies improvements to quality and effectiveness.', ARRAY[]::text[], 'Sections 4.2 and 8', 5, 'reflects on their performance', TRUE, CURRENT_TIMESTAMP),
('PRODUCT_OWNER', 'Product Owner', 'SCRUM_ROLE', 'The Scrum role responsible for ordering the Product Backlog and collaborating with the Scrum team on identifying and defining Primary Use Cases in Colony.', ARRAY['PO']::text[], 'Sections 4.2 and 6.1', 5, 'Product Owner', TRUE, CURRENT_TIMESTAMP),
('DEVELOPMENT_TEAM', 'Development Team', 'SCRUM_ROLE', 'The team that performs development work, selects and plans Sprint work, designs and verifies inquiries, and implements the product.', ARRAY[]::text[], 'Sections 4.2, 6.2, 6.3', 5, 'Development Team', TRUE, CURRENT_TIMESTAMP),
('SCRUM_MASTER', 'Scrum Master', 'SCRUM_ROLE', 'The Scrum role described as facilitating Sprint Planning, Daily Scrum, Sprint Review, and Sprint Retrospective activities.', ARRAY[]::text[], 'Sections 4.2 and 4.2 process description', 5, 'Scrum Master', TRUE, CURRENT_TIMESTAMP),
('PRIMARY_USE_CASE', 'Primary Use Case', 'COLONY_CORE', 'A high-priority initial Use Case identified from the most important activities of important organizational units. It is used to identify and plan the initial Product Backlog and can trigger other Use Cases through Request or Invitation reactions.', ARRAY['PUC', 'Primary Use cases']::text[], 'Section 6.1: Product Backlog Planning', 9, 'novel and efficient way', TRUE, CURRENT_TIMESTAMP),
('USE_CASE', 'Use Case', 'COLONY_CORE', 'A description of how a system interacts with a user or another system to achieve a goal. In Colony, Use Cases belong to the Product Backlog and are elaborated through associated Sprint Backlog work.', ARRAY['UC', 'Use cases']::text[], 'Sections 6.1 and 6.2', 9, 'interacts with a user', TRUE, CURRENT_TIMESTAMP),
('USE_CASE_DEFINITION', 'Use Case Definition', 'COLONY_WORK_ITEM', 'The Product Backlog work item that defines a Use Case before its Elaboration. Table 1 shows it as a Use Case update from Create to Ready.', ARRAY[]::text[], 'Table 1, row 3', 13, 'Use case Definition', TRUE, CURRENT_TIMESTAMP),
('ELEMENT', 'Element', 'COLONY_CORE', 'A representation of a Use Case and everything involved in it, including manipulated objects, events that trigger actions, and reactions resulting from those actions.', ARRAY[]::text[], 'Section 6.2', 9, 'representation of a Use case', TRUE, CURRENT_TIMESTAMP),
('USE_CASE_COLONY', 'Use Case Colony', 'COLONY_CORE', 'A group or network of related Elements connected through Request reactions for requirements and Invitation reactions for products. The colony expands as dependent Use Cases are identified.', ARRAY['Colony of Use cases']::text[], 'Sections 6.1, 6.2 and Fig. 6', 9, 'group of related elements', TRUE, CURRENT_TIMESTAMP),
('INCEPTION', 'Inception', 'COLONY_PHASE', 'The initial Colony phase in which Primary Use Cases are identified and the initial Product Backlog is planned. It corresponds to the initial vision and estimate objective discussed with the Unified Process.', ARRAY[]::text[], 'Section 6.1 and Table 1 row 1', 8, 'Inception phase', TRUE, CURRENT_TIMESTAMP),
('ELABORATION', 'Elaboration', 'COLONY_PHASE', 'The phase in which each Use Case is elaborated through Sprint Backlog inquiries, Activity Diagram design, and the identification of requirements and products until no further inquiry is generated.', ARRAY['ELB']::text[], 'Sections 6.2 and Table 1 rows 4-35', 9, 'Elaboration phase', TRUE, CURRENT_TIMESTAMP),
('CONSTRUCTION', 'Construction', 'COLONY_PHASE', 'The phase that starts when a Use Case reaches Done after Elaboration. It includes code generation, implementation, and the specified tests.', ARRAY[]::text[], 'Section 6.3 and Table 1 rows 36-41', 11, 'Construction phase', TRUE, CURRENT_TIMESTAMP),
('TRANSITION', 'Transition', 'COLONY_PHASE', 'The phase following Construction, including demo, beta testing, interface testing, parallel operation testing, data conversion, and user training.', ARRAY[]::text[], 'Section 6.4 and Table 1 rows 42-47', 11, 'Transition phase', TRUE, CURRENT_TIMESTAMP),
('MAINTENANCE', 'Maintenance', 'COLONY_PHASE', 'The phase in which changes requiring a new Use Case add a Product Backlog item, while changes to existing Elements modify Sprint Backlog work and repeat Elaboration for that Element.', ARRAY[]::text[], 'Section 6.5 and Table 1 rows 48-50', 12, 'Maintenance phase', TRUE, CURRENT_TIMESTAMP),
('AUTOMATED_PLANNING', 'Automated Planning', 'COLONY_PROCESS', 'The Colony planning mechanism through which inquiries and reactions generate and prioritize Product Backlog and Sprint Backlog work, forming a connected Use Case colony.', ARRAY[]::text[], 'Sections 3, 6.1, 6.2 and 8', 3, 'automated planning mechanism', TRUE, CURRENT_TIMESTAMP),
('EVENT', 'Event', 'COLONY_INTERACTION', 'A named occurrence in the Colony lifecycle that initiates or represents an activity and is related to a Reaction, Inquiry, Action, states, backlog, and priority in Table 1.', ARRAY[]::text[], 'Section 6 and Table 1', 8, 'types of Events', TRUE, CURRENT_TIMESTAMP),
('INQUIRY', 'Inquiry', 'COLONY_INTERACTION', 'A question or request specifying what the system should do or provide. In Colony, inquiries create Sprint Backlog work and may lead to further Use Cases in the Product Backlog.', ARRAY[]::text[], 'Section 6.2', 9, 'question or request', TRUE, CURRENT_TIMESTAMP),
('REACTION', 'Reaction', 'COLONY_INTERACTION', 'A Colony interaction type represented in Table 1, particularly Request and Invitation, through which Use Cases are connected based on requirements and products.', ARRAY[]::text[], 'Sections 6.1, 6.2 and Table 1', 8, 'Request and Invitation', TRUE, CURRENT_TIMESTAMP),
('REQUEST', 'Request', 'COLONY_REACTION', 'A reaction that occurs when a Use Case needs another Use Case to perform vital activities or satisfy a requirement; it can lead to a new Use Case inquiry in the Product Backlog.', ARRAY[]::text[], 'Sections 6.1, 6.2 and 6.5', 8, 'needs to perform', TRUE, CURRENT_TIMESTAMP),
('INVITATION', 'Invitation', 'COLONY_REACTION', 'A reaction that occurs when a Use Case creates or changes data or products for other Use Cases to use; it can connect additional Use Cases to the colony.', ARRAY[]::text[], 'Sections 6.1, 6.2 and 6.5', 8, 'creates or changes some data', TRUE, CURRENT_TIMESTAMP),
('ACTIVITY_DIAGRAM', 'Activity Diagram', 'MODEL', 'A graphical model showing the action flows in a Use Case. In Colony it is progressively upgraded with Events and Inquiries until no more inquiries are generated.', ARRAY[]::text[], 'Sections 6.2 and 6.2.1; Table 1 rows 6 and 35', 9, 'graphical model showing', TRUE, CURRENT_TIMESTAMP),
('OBJECT_ACTION', 'Object Action', 'MODEL', 'A Colony work item or model element representing an action involving an object. Table 1 distinguishes Object Action work associated with requirements and products.', ARRAY[]::text[], 'Section 6.2 and Table 1 rows 7-26', 9, 'Object Action', TRUE, CURRENT_TIMESTAMP),
('REQUIRED_INFORMATION', 'Required Information', 'COLONY_OBJECT', 'A requirement-side inquiry or work item representing information needed by an activity. Table 1 links it to Actor inquiry and subsequent design work.', ARRAY[]::text[], 'Table 1 rows 8-11; Section 7.3.2', 13, 'Required information', TRUE, CURRENT_TIMESTAMP),
('REQUIRED_OBJECT', 'Required Object', 'COLONY_OBJECT', 'A requirement-side object needed by a Use Case. Table 1 links it to a Class inquiry, possible Request reaction, and Class Diagram design.', ARRAY[]::text[], 'Table 1 rows 12-16; Section 7.3.2', 13, 'Required object', TRUE, CURRENT_TIMESTAMP),
('PRODUCED_OBJECT', 'Produced Object', 'COLONY_OBJECT', 'An object produced by a Use Case. Table 1 links it to a Class inquiry and possible Invitation reaction to other Use Cases.', ARRAY[]::text[], 'Table 1 rows 17-21', 13, 'Produced Object', TRUE, CURRENT_TIMESTAMP),
('OUTPUT', 'Output', 'COLONY_OBJECT', 'An output work item produced by an Object Action. Table 1 links Output to an Actor inquiry and Output Report design.', ARRAY[]::text[], 'Table 1 rows 22-25; Section 7.3.2', 13, 'Output', TRUE, CURRENT_TIMESTAMP),
('ACTOR', 'Actor', 'COLONY_ACTOR', 'An external person or entity interacting with the system or associated with required information or products. Table 1 creates or selects Actor records for requirement and product contexts.', ARRAY[]::text[], 'Table 1 rows 9-10 and 23-24; Section 7.3.2', 13, 'Actor', TRUE, CURRENT_TIMESTAMP),
('EXTERNAL_ACTOR', 'External Actor', 'COLONY_ACTOR', 'An actor outside the system boundary who participates in a Use Case. The real-sample section illustrates a customer as an external actor.', ARRAY[]::text[], 'Section 7.3.2 and Table 5', 25, 'External Actor', TRUE, CURRENT_TIMESTAMP),
('CLASS', 'Class', 'MODEL', 'A class identified for a required or produced object. In the Colony lifecycle, a Class inquiry may lead to a new Use Case through Request or Invitation reactions.', ARRAY[]::text[], 'Table 1 rows 13-20; Section 6.2', 13, 'Class', TRUE, CURRENT_TIMESTAMP),
('CLASS_DIAGRAM', 'Class Diagram', 'MODEL', 'A design model requested as an Inquiry to represent classes associated with the Use Case and its objects.', ARRAY[]::text[], 'Section 6.2 and Table 1 row 16', 9, 'Class Diagram', TRUE, CURRENT_TIMESTAMP),
('OBJECT_ACTION_DIAGRAM', 'Object Action Diagram', 'MODEL', 'A design report or diagram associated with an Object Action, describing the objects and their actions.', ARRAY[]::text[], 'Section 6.2 and Table 1 row 21', 9, 'Object Action Diagram', TRUE, CURRENT_TIMESTAMP),
('INCLUDE', 'Include', 'USE_CASE_RELATIONSHIP', 'A Use Case relationship identified as an Activity Diagram inquiry. In the sample, an Include inquiry leads to a Request reaction and a new Use Case.', ARRAY[]::text[], 'Table 1 rows 27-28; Section 7.3.2', 13, 'Include', TRUE, CURRENT_TIMESTAMP),
('EXTEND', 'Extend', 'USE_CASE_RELATIONSHIP', 'A Use Case relationship identified as an Activity Diagram inquiry. In the sample, an Extend inquiry leads to a Request reaction and a new Use Case.', ARRAY[]::text[], 'Table 1 rows 29-30; Section 7.3.2', 13, 'Extend', TRUE, CURRENT_TIMESTAMP),
('DECISION_POINT', 'Decision Point', 'MODEL', 'A decision-related inquiry generated from the Activity Diagram and followed by design work represented as a Decision Matrix.', ARRAY[]::text[], 'Table 1 rows 31-32', 13, 'Decision point', TRUE, CURRENT_TIMESTAMP),
('DECISION_MATRIX', 'Decision Matrix', 'MODEL', 'The design output associated with a Decision Point inquiry in Table 1.', ARRAY[]::text[], 'Table 1 row 32', 13, 'Decision Matrix', TRUE, CURRENT_TIMESTAMP),
('CONDITION_TABLE', 'Condition Table', 'CONTROL_MODEL', 'A table that controls conditions for accepting input data and automatically changing final states. It records class, trigger event, order, start status, final state, trimming time, and validation contract.', ARRAY[]::text[], 'Section 6.2.1 and Table 1 rows 33-34', 10, 'controls the conditions', TRUE, CURRENT_TIMESTAMP),
('TRIGGER_EVENT', 'Trigger Event', 'CONTROL_TERM', 'An event that activates an Element, identified as one of the fields in a Condition Table.', ARRAY[]::text[], 'Section 6.2.1', 10, 'event that activates', TRUE, CURRENT_TIMESTAMP),
('START_STATE', 'Start State', 'CONTROL_TERM', 'The acceptable status code for accepting records, used to determine a filter that passes specific data from a specific class. Table 1 associates Start State values with lifecycle transitions.', ARRAY[]::text[], 'Section 6.2.1 and Table 1', 10, 'acceptable status code', TRUE, CURRENT_TIMESTAMP),
('FINAL_STATE', 'Final State', 'CONTROL_TERM', 'The status code marking termination of an Element''s activity; it can cause a record to be sent to another Element and removed from the current cartable.', ARRAY[]::text[], 'Section 6.2.1', 10, 'termination of the element', TRUE, CURRENT_TIMESTAMP),
('TRIMMING_TIME', 'Trimming Time', 'CONTROL_TERM', 'The approximate duration of data processing in an Element, used to prepare decision reports about transaction volume and compatibility with the number of users.', ARRAY[]::text[], 'Section 6.2.1', 10, 'approximate duration', TRUE, CURRENT_TIMESTAMP),
('VALIDATION_CONTRACT', 'Validation Contract', 'CONTROL_MODEL', 'A table that checks the validity of input values when a record''s state changes.', ARRAY[]::text[], 'Section 6.2.1', 10, 'checks the validity', TRUE, CURRENT_TIMESTAMP),
('STATE_DIAGRAM', 'State Diagram', 'MODEL', 'A model used with the Condition Table to construct and represent the scope of an Element''s states.', ARRAY[]::text[], 'Section 7.3.2', 26, 'state diagram', TRUE, CURRENT_TIMESTAMP),
('CODE_GENERATION', 'Code Generation', 'COLONY_EVENT', 'The Construction-phase event in which a code generator creates draft code from Activity Diagram data, after which the development team examines documentation and creates the main code.', ARRAY[]::text[], 'Section 6.3 and Table 1 row 37', 11, 'Code Generation event', TRUE, CURRENT_TIMESTAMP),
('CODE_GENERATOR', 'Code Generator', 'TOOL_CONCEPT', 'A tool that automatically generates draft code from a graphical model, using standard default features set in the Activity Diagram.', ARRAY[]::text[], 'Section 6.3', 11, 'automatically generates code', TRUE, CURRENT_TIMESTAMP),
('INTERACTION_OBJECTS_TEST', 'Interaction Objects Test', 'TEST', 'The first Construction test described in Table 1; it checks interaction of objects in the software and is partly supported by Invitation and Request generation.', ARRAY['IOTEST']::text[], 'Section 6.3 and Table 1 row 38', 11, 'Interaction Objects Test', TRUE, CURRENT_TIMESTAMP),
('INTEGRATION_TEST', 'Integration Test', 'TEST', 'A test that starts with an event of the same name in the Sprint Backlog and checks data integrity after each action object is created.', ARRAY[]::text[], 'Section 6.3 and Table 1 row 39', 11, 'Integration Test', TRUE, CURRENT_TIMESTAMP),
('NO_ENTRY', 'No Entry', 'INTEGRATION_TEST_CASE', 'An output item that is not used in any Element; the article associates this condition with an Invitation reaction.', ARRAY[]::text[], 'Section 6.3', 11, 'output item that is not used', TRUE, CURRENT_TIMESTAMP),
('NO_OUTPUT', 'No Output', 'INTEGRATION_TEST_CASE', 'An input item that has no output in any Element; the article associates this condition with a Request reaction.', ARRAY[]::text[], 'Section 6.3', 11, 'input item that has no output', TRUE, CURRENT_TIMESTAMP),
('ACKNOWLEDGE_TEST', 'Acknowledge Test', 'TEST', 'The test intended to ensure software quality by finding and fixing defects, validating requirements, and verifying functionality; part of it is automatically covered by the Condition Table.', ARRAY['Acknowledgment Test']::text[], 'Section 6.3 and Table 1 row 40', 11, 'finding and fixing defects', TRUE, CURRENT_TIMESTAMP),
('PREPARE_USER_GUIDE', 'Prepare User Guide', 'COLONY_EVENT', 'A Construction-phase activity in Table 1 that prepares the User Guide and moves the Use Case toward Demo.', ARRAY[]::text[], 'Table 1 row 41 and Section 6.3', 14, 'Prepare User Guide', TRUE, CURRENT_TIMESTAMP),
('BETA_TESTING', 'Beta Testing', 'TEST', 'A Transition-phase test listed in Table 1 after Present Demo.', ARRAY['BETTES']::text[], 'Section 6.4 and Table 1 row 43', 11, 'Beta Testing', TRUE, CURRENT_TIMESTAMP),
('INTERFACE_TESTING', 'Interface Testing', 'TEST', 'A Transition-phase test listed in Table 1 after Beta Testing.', ARRAY['IFTEST']::text[], 'Section 6.4 and Table 1 row 44', 11, 'Interface Testing', TRUE, CURRENT_TIMESTAMP),
('PARALLEL_OPERATION_TEST', 'Parallel Operation Test', 'TEST', 'A Transition-phase test listed in Table 1 after Interface Testing.', ARRAY['PAROPT']::text[], 'Section 6.4 and Table 1 row 45', 11, 'Parallel Operation Test', TRUE, CURRENT_TIMESTAMP),
('DATA_CONVERSION', 'Data Conversion', 'TRANSITION_ACTIVITY', 'A Transition-phase activity listed in Table 1 after Parallel Operation Test.', ARRAY['DATCON']::text[], 'Section 6.4 and Table 1 row 46', 11, 'Data Conversion', TRUE, CURRENT_TIMESTAMP),
('USER_TRAINING', 'User Training', 'TRANSITION_ACTIVITY', 'A Transition-phase activity listed in Table 1 after Data Conversion.', ARRAY[]::text[], 'Section 6.4 and Table 1 row 47', 11, 'User training', TRUE, CURRENT_TIMESTAMP),
('PRESENT_DEMO', 'Present Demo', 'TRANSITION_ACTIVITY', 'A Transition-phase activity in which the Use Case demo is presented.', ARRAY[]::text[], 'Section 6.4 and Table 1 row 42', 11, 'Present Demo', TRUE, CURRENT_TIMESTAMP),
('FEEDBACK', 'Feedback', 'COLONY_PROCESS', 'A continuous feedback mechanism through which users submit requirements and suggestions; the development team decides whether to improve an existing Element or create a new Element/Use Case.', ARRAY[]::text[], 'Sections 6.4.1 and 8', 12, 'automatic feedback system', TRUE, CURRENT_TIMESTAMP),
('STAKEHOLDER_ANALYSIS', 'Stakeholder Analysis', 'ANALYSIS_PROCESS', 'A process involving analysis of stakeholder needs and feedback, communication with stakeholders, and review and updating of the analysis. The article notes identifying and categorizing stakeholders as remaining steps.', ARRAY[]::text[], 'Section 6.4.2', 12, 'Analyze the stakeholders', TRUE, CURRENT_TIMESTAMP),
('STAKEHOLDER', 'Stakeholder', 'ROLE_CONCEPT', 'A person or group whose needs, expectations, preferences, motivations, concerns, or risks are considered in product development and stakeholder analysis.', ARRAY[]::text[], 'Sections 6.4.2 and 7.3.2', 12, 'needs, expectations', TRUE, CURRENT_TIMESTAMP),
('REQUIREMENT', 'Requirement', 'REQUIREMENT_CONCEPT', 'A need or specification that a Use Case must address. In Colony, requirements can generate one or more Requests in the Sprint Backlog and are prioritized relative to their parent Use Case.', ARRAY[]::text[], 'Sections 6.2, 6.5 and Table 1', 9, 'Each Requirement', TRUE, CURRENT_TIMESTAMP),
('FUNCTIONAL_REQUIREMENT', 'Functional Requirement', 'REQUIREMENT_TYPE', 'A requirement concerning functionality to be handled by the product; the article lists functional requirements among the types Colony can handle.', ARRAY[]::text[], 'Section 8: Summary and Conclusion', 27, 'functional', TRUE, CURRENT_TIMESTAMP),
('NONFUNCTIONAL_REQUIREMENT', 'Non-functional Requirement', 'REQUIREMENT_TYPE', 'A requirement concerning qualities or constraints such as security, scalability, and maintainability; the article discusses these as requirements that can be neglected or addressed through Condition Tables.', ARRAY['NFR']::text[], 'Sections 5.2, 6.2.1 and 8', 7, 'scalability and maintainability', TRUE, CURRENT_TIMESTAMP),
('CONSTRAINT', 'Constraint', 'REQUIREMENT_TYPE', 'A limiting condition or restriction; constraints are listed among the requirement types Colony can handle.', ARRAY[]::text[], 'Section 8: Summary and Conclusion', 27, 'constraints', TRUE, CURRENT_TIMESTAMP),
('ASSUMPTION', 'Assumption', 'REQUIREMENT_TYPE', 'An assumed condition considered in product development feasibility and listed among the requirement types Colony can handle.', ARRAY[]::text[], 'Section 8: Summary and Conclusion', 27, 'assumptions', TRUE, CURRENT_TIMESTAMP),
('USER_STORY', 'User Story', 'AGILE_PRACTICE', 'A short, user-perspective description of what a user wants to do and why, focusing on value and initiating conversation rather than specifying detailed requirements or solutions. The article identifies card, conversation, and confirmation as its components.', ARRAY[]::text[], 'Section 4.2 and Section 6.1', 5, 'short descriptions', TRUE, CURRENT_TIMESTAMP),
('STORY_POINT', 'Story Point', 'ESTIMATION', 'A relative, abstract measure of effort based on complexity, uncertainty, and risk rather than elapsed time; the article mentions Fibonacci-like scales.', ARRAY[]::text[], 'Sections 4.2 and 7.3.1', 5, 'abstract measure of effort', TRUE, CURRENT_TIMESTAMP),
('TIME_ESTIMATION', 'Time Estimation', 'ESTIMATION', 'The amount of time or effort required to complete a User Story, expressed in hours or days and estimated by breaking the story into smaller tasks.', ARRAY[]::text[], 'Section 7.3.1', 25, 'amount of time or effort', TRUE, CURRENT_TIMESTAMP),
('STORY_SCORE', 'Story Score', 'ESTIMATION', 'A measure described in the article as the product of Time Estimation and Story Point for a User Story.', ARRAY[]::text[], 'Section 7.3.1', 25, 'product of time estimation', TRUE, CURRENT_TIMESTAMP),
('TASK_DIFFICULTY_SCORE', 'Task Difficulty Score', 'ESTIMATION', 'A relative score used to encourage team members to commit to a task; the article states that it ranges from 1 to 100.', ARRAY['TDS', 'TSD (as printed in explanatory sentence)']::text[], 'Section 7.3.1', 25, 'ranges from 1 to 100', TRUE, CURRENT_TIMESTAMP),
('SPRINT_GOAL', 'Sprint Goal', 'SCRUM_CONCEPT', 'A short statement summarizing what the team wants to achieve during a Sprint and providing shared direction and focus.', ARRAY[]::text[], 'Section 7.3.2', 25, 'short statement', TRUE, CURRENT_TIMESTAMP),
('MOSCOW', 'MoSCoW method', 'PRIORITIZATION', 'A prioritization technique with four categories: Must-have, Should-have, Could-have, and Won''t-have.', ARRAY['MoSCoW']::text[], 'Section 4.2', 5, 'Must-have, Should-have', TRUE, CURRENT_TIMESTAMP),
('SMART', 'SMART', 'QUALITY_CRITERIA', 'A goal-setting framework represented by Specific, Measurable, Achievable, Relevant, and Time-bound criteria.', ARRAY[]::text[], 'Section 4.2 and Section 6.1', 5, 'Specific, Measurable', TRUE, CURRENT_TIMESTAMP),
('INVEST', 'INVEST', 'QUALITY_CRITERIA', 'A set of criteria for assessing User Stories or Product Backlog items: Independent, Negotiable, Valuable, Estimable, Small, and Testable.', ARRAY[]::text[], 'Section 4.2', 5, 'Independent, Negotiable', TRUE, CURRENT_TIMESTAMP),
('TRANSPARENCY', 'Transparency', 'SCRUM_PILLAR', 'A pillar of Scrum empiricism requiring important aspects of the process to be visible to those responsible for results. The article relates it to Colony''s common messages and inquiry types.', ARRAY[]::text[], 'Sections 4.2 and 8', 4, 'visible to those responsible', TRUE, CURRENT_TIMESTAMP),
('INSPECTION', 'Inspection', 'SCRUM_PILLAR', 'A pillar of Scrum empiricism used to detect unfavorable variances in progress toward the Sprint Goal. The article relates it to inspection of Colony productions.', ARRAY[]::text[], 'Sections 4.2 and 8', 4, 'detect unfavorable variances', TRUE, CURRENT_TIMESTAMP),
('ADAPTATION', 'Adaptation', 'SCRUM_PILLAR', 'A pillar of Scrum empiricism requiring adjustments when a process deviates from an acceptable range. The article relates it to Colony''s dependency logic and response to change.', ARRAY[]::text[], 'Sections 4.2 and 8', 4, 'adjustments should be made', TRUE, CURRENT_TIMESTAMP),
('SELF_ORGANIZATION', 'Self-organization', 'AGILE_PRINCIPLE', 'A principle associated with agile teams and listed among the Scrum principles considered in the methodology evaluation.', ARRAY[]::text[], 'Sections 4.1 and 7.2', 4, 'self-organization', TRUE, CURRENT_TIMESTAMP),
